"""Read-only cleaning inspector for the production workbench."""

CLEANING_HTML = '''<section id="board-cleaning" class="board-cleaning" aria-labelledby="board-cleaning-title" hidden><div class="cleaning-heading"><h3 id="board-cleaning-title">清洗结果</h3><button id="board-cleaning-refresh" type="button">刷新结果</button></div><p id="board-cleaning-status" role="status" aria-live="polite"></p><div id="board-cleaning-body"></div></section>'''

CLEANING_CSS = '''
.cleaning-chain{margin:14px 0 24px}.cleaning-step-nav{display:flex;gap:8px;overflow-x:auto;padding:2px 0 12px;scrollbar-width:thin}.cleaning-step-tab{flex:0 0 auto;min-width:190px;max-width:270px;text-align:left;background:#f4f7f3}.cleaning-step-tab[aria-selected="true"]{border-color:#246646;background:#e8f3e9;color:#174b2d}.cleaning-step-tab strong,.cleaning-step-tab small{display:block}.cleaning-step-tab small{margin-top:4px;font-size:11px;color:#69736b}.cleaning-step-results>.cleaning-step{border:1px solid #dedfdb;border-radius:10px;padding:14px;background:#fff}.cleaning-step-results>.cleaning-step:not([open]){display:none}.cleaning-node-info{margin:14px 0;color:#69736b;font-size:13px}.cleaning-history-run{border-top:1px solid #e5e8e4;padding:12px 0}.cleaning-history-run>summary{cursor:pointer;font-weight:600;color:#46594b}.cleaning-thumbnail{display:block;width:100%;min-height:200px;padding:0;border:0;border-radius:6px;background:#f6f6f4;cursor:zoom-in;margin-bottom:10px}.cleaning-image p{font-size:13px}
.board-cleaning{margin-top:16px;padding-top:16px;border-top:1px solid #dedfdb}.board-cleaning[hidden],#board-cleaning-status:empty{display:none}.board-cleaning p{overflow-wrap:anywhere;font-size:13px;line-height:1.6}.cleaning-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.cleaning-heading h3{margin:0 auto 0 0}.cleaning-snapshot{padding:12px;background:#f3f6f2;border-radius:10px;margin:12px 0}.cleaning-step{border-top:1px solid #dedfdb;padding:14px 0}.cleaning-step summary{cursor:pointer;font-weight:700}.cleaning-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin:12px 0}.cleaning-image{border:1px solid #dedfdb;border-radius:10px;padding:12px;min-width:0}.cleaning-image img{display:block;width:100%;height:200px;object-fit:contain;background:#f6f6f4}.cleaning-image small{overflow-wrap:anywhere;display:block;color:#69736b}.cleaning-filters{display:flex;gap:10px;flex-wrap:wrap;margin:12px 0}.cleaning-filters select,.cleaning-filters input{padding:8px;border:1px solid #dedfdb;border-radius:8px;max-width:100%}
'''

CLEANING_JS = r'''
const cleaningPanel={taskId:null,token:0,timer:null,abort:null,urls:new Set(),filters:new Map(),deactivate:null,openKey:null,firstStep:null,imageQueue:[],imageActive:0,imageRows:new Set()};
function mountBoardCleaning(item,body){openBoardCleaning(item.task_id)}
function cleaningText(parent,tag,text){const el=document.createElement(tag);el.textContent=text;parent.append(el);return el}
function boardCleaningReason(reason){const labels={MATCH:'符合条件',MISMATCH:'不符合条件',FACT_UNAVAILABLE:'证据不足',DETECTOR_ERROR:'检测器异常',DETECTOR_OUTPUT_INVALID:'检测结果格式无效'};return `${reason.rule_id}：${labels[reason.reason_code]||reason.reason_code}（${reason.verdict}）`+(reason.reason_summary?`：${reason.reason_summary}${reason.reason_truncated?'（摘要已截断）':''}`:reason.verdict==='pass'?'':'；未保存具体原因摘要')}
function boardCleaningItems(step,filter){return step.items.filter(item=>(filter.status==='all'||item.status===filter.status)&&(!filter.tag||filter.tag==='all'||item.reasons.some(reason=>filter.tag==='rule:'+reason.rule_id||filter.tag==='reason:'+reason.reason_code))&&(!filter.query||item.reasons.some(reason=>boardCleaningReason(reason).includes(filter.query))))}
function clearBoardCleaning(){cleaningPanel.deactivate?.(true);cleaningPanel.deactivate=null;cleaningPanel.firstStep=null;for(const job of cleaningPanel.imageQueue){job.row._imagePending=false;job.resolve()}cleaningPanel.imageQueue=[];for(const row of cleaningPanel.imageRows)releaseCleaningRow(row);cleaningPanel.imageRows.clear();clearTimeout(cleaningPanel.timer);cleaningPanel.timer=null;cleaningPanel.abort?.abort();cleaningPanel.abort=null;for(const url of cleaningPanel.urls)URL.revokeObjectURL(url);cleaningPanel.urls.clear()}
function closeBoardCleaning(){if(typeof assetViewer!=='undefined'&&$('asset-viewer').open)$('asset-viewer').close();cleaningPanel.token++;cleaningPanel.taskId=null;clearBoardCleaning();cleaningPanel.openKey=null;$('board-cleaning').hidden=true;$('board-cleaning-body').replaceChildren()}
function boardCleaningSnapshot(parent,execution){const box=document.createElement('div');box.className='cleaning-snapshot';parent.append(box);if(!execution?.model){cleaningText(box,'p','未保存 VLM 执行快照，不使用当前配置补写历史模型和指令。');if(execution?.backend_refs)cleaningText(box,'p','算子：'+execution.backend_refs.join('、'));return}cleaningText(box,'p',`清洗模型：${execution.model.provider} / ${execution.model.name}（${execution.model.id}）`);cleaningText(box,'p','执行指令：'+execution.instruction);cleaningText(box,'p',`算子：${execution.backend_ref} · 提示版本：${execution.prompt_version}`);cleaningText(box,'small','配置摘要：'+execution.config_digest)}
async function fetchBoardCleaningImage(taskId,candidateId,row,button,token){button.disabled=true;button.textContent='加载缩略图…';try{const response=await fetch(`/v1/retrieval/tasks/${encodeURIComponent(taskId)}/cleaning/candidates/${encodeURIComponent(candidateId)}/preview`,{headers,cache:'no-store',signal:row._imageAbort.signal});if(!response.ok)throw new Error('图片不可读取或已撤权');const blob=await response.blob();if(!['image/jpeg','image/png'].includes(blob.type)||blob.size>10*1024*1024)throw new Error('图片格式或大小无效');if(token!==cleaningPanel.token||row._imageAbort.signal.aborted||!row.isConnected)return;const url=URL.createObjectURL(blob);cleaningPanel.urls.add(url);row._previewUrl=url;const img=document.createElement('img');img.alt='清洗图片，点击查看证据';img.src=url;img.onerror=()=>{releaseCleaningRow(row);button.replaceChildren();button.textContent='图片解码失败，点击重试';button.onclick=()=>boardCleaningImage(taskId,candidateId,row,button,token)};button.textContent='';button.replaceChildren(img);button.disabled=false;button.onclick=()=>openAssetViewer(row)}catch(error){if(error.name!=='AbortError'&&token===cleaningPanel.token&&row.isConnected){button.disabled=false;button.textContent=error.message+'，点击重试';button.onclick=()=>boardCleaningImage(taskId,candidateId,row,button,token)}}}
function boardCleaningImage(taskId,candidateId,row,button,token){
 if(row._imagePending)return;row._imagePending=true;row._imageAbort=new AbortController();cleaningPanel.imageRows.add(row);button.disabled=true;
 return new Promise(resolve=>{cleaningPanel.imageQueue.push({taskId,candidateId,row,button,token,resolve});pumpCleaningImages()});
}
function pumpCleaningImages(){while(cleaningPanel.imageActive<4&&cleaningPanel.imageQueue.length){const job=cleaningPanel.imageQueue.shift();if(job.token!==cleaningPanel.token||job.row._imageAbort.signal.aborted||!job.row.isConnected){job.row._imagePending=false;job.resolve();continue}cleaningPanel.imageActive++;fetchBoardCleaningImage(job.taskId,job.candidateId,job.row,job.button,job.token).finally(()=>{job.row._imagePending=false;cleaningPanel.imageActive--;job.resolve();pumpCleaningImages()})}}
function releaseCleaningRow(row){cleaningPanel.imageQueue=cleaningPanel.imageQueue.filter(job=>{if(job.row!==row)return true;job.row._imagePending=false;job.resolve();return false});row._imageAbort?.abort();cleaningPanel.imageRows.delete(row);if(row._previewUrl){URL.revokeObjectURL(row._previewUrl);cleaningPanel.urls.delete(row._previewUrl);row._previewUrl=null}}
function boardCleaningTags(step){const tags=new Map();for(const item of step.items)for(const reason of item.reasons){tags.set('rule:'+reason.rule_id,'规则：'+reason.rule_id);tags.set('reason:'+reason.reason_code,'原因：'+({MATCH:'符合条件',MISMATCH:'不符合条件',FACT_UNAVAILABLE:'证据不足',DETECTOR_ERROR:'检测器异常',DETECTOR_OUTPUT_INVALID:'检测结果格式无效'}[reason.reason_code]||reason.reason_code))}return tags}
function boardCleaningStep(parent,run,step,taskId,preview,token,index=0){
 const key=run.operation_id+':'+run.output_version+':'+step.step_id;
 const filter=cleaningPanel.filters.get(key)||{status:'all',query:'',tag:'all',expanded:false};cleaningPanel.filters.set(key,filter);
 const tab=document.createElement('button');tab.type='button';tab.className='cleaning-step-tab';tab.setAttribute('aria-selected','false');const title=cleaningText(tab,'strong',`节点 ${index+1}`);cleaningText(tab,'small',`输入 ${step.counts.input} · 保留 ${step.counts.retained} · 淘汰 ${step.counts.rejected} · 待复核 ${step.counts.review}`);parent._nav.append(tab);
 const detail=document.createElement('details');detail.className='cleaning-step';parent._results.append(detail);tab.onclick=()=>{if(!detail.open)detail.open=true};
 cleaningText(detail,'summary',`节点 ${index+1} · 逐图结果`);
 const metadata=document.createElement('details');metadata.className='cleaning-node-info';detail.append(metadata);cleaningText(metadata,'summary','查看节点规则与执行信息');cleaningText(metadata,'p',`算子：${step.backend_ref} · 输出版本：${run.output_version}`);
 const node=run.execution?.nodes?.find(item=>item.backend_ref===step.backend_ref);if(node){cleaningText(metadata,'p','对应诉求：'+node.source);cleaningText(metadata,'p','本节点指令：'+node.instruction)}for(const rule of step.rules)cleaningText(metadata,'p',`${rule.rule_id}：${rule.predicate} ${rule.operator} ${JSON.stringify(rule.value)}`);
 const controls=document.createElement('div');controls.className='cleaning-filters';detail.append(controls);
 const select=document.createElement('select');select.setAttribute('aria-label',step.step_id+' 筛选清洗结果');for(const [value,label] of [['all','全部图片'],['retained','本步保留'],['rejected','淘汰'],['review','待复核'],['pending','未完成'],['blocked','阻塞']]){const option=cleaningText(select,'option',label);option.value=value}select.value=filter.status;
 const tags=document.createElement('select');tags.setAttribute('aria-label',step.step_id+' 筛选规则或原因标签');const all=cleaningText(tags,'option','全部标签');all.value='all';
 for(const rule of step.rules){const option=cleaningText(tags,'option','规则：'+rule.rule_id);option.value='rule:'+rule.rule_id}
 for(const [code,label] of Object.entries({MATCH:'符合条件',MISMATCH:'不符合条件',FACT_UNAVAILABLE:'证据不足',DETECTOR_ERROR:'检测器异常',DETECTOR_OUTPUT_INVALID:'检测结果格式无效'})){const option=cleaningText(tags,'option','原因：'+label);option.value='reason:'+code}tags.value=filter.tag;
 const query=document.createElement('input');query.type='search';query.maxLength=200;query.placeholder='搜索全部原因或规则';query.setAttribute('aria-label',step.step_id+' 搜索清洗原因');query.value=filter.query;controls.append(select,tags,query);
 const count=cleaningText(detail,'p','展开节点后读取图片'),grid=document.createElement('div');grid.className='cleaning-grid';detail.append(grid);
 const prev=cleaningText(detail,'button','上一页图片'),next=cleaningText(detail,'button','下一页图片'),retry=cleaningText(detail,'button','重试读取图片');retry.hidden=true;
 let cursors=[null],page=0,nextCursor=null,epoch=0,loaded=false,loading=false,searchTimer=null,requestAbort=null;
 const rows=new Set();
 const release=()=>{for(const row of rows)releaseCleaningRow(row);rows.clear();grid.replaceChildren();if(typeof assetViewer!=='undefined'&&$('asset-viewer').open)$('asset-viewer').close()};
 const buttons=()=>{prev.disabled=loading||page===0;next.disabled=loading||!nextCursor};
 const current=e=>token===cleaningPanel.token&&epoch===e&&detail.open&&taskId===cleaningPanel.taskId;
 const deactivate=(preserve=false)=>{tab.setAttribute('aria-selected','false');if(!preserve&&cleaningPanel.openKey===key)cleaningPanel.openKey="";epoch++;clearTimeout(searchTimer);requestAbort?.abort();loading=false;loaded=false;filter.expanded=false;detail.open=false;release();buttons()};
 async function load(target=0,cursor=null){
  clearTimeout(searchTimer);requestAbort?.abort();requestAbort=new AbortController();const e=++epoch;loading=true;retry.hidden=true;buttons();release();count.textContent='正在读取本页图片…';
  const params=new URLSearchParams({operation_id:run.operation_id,step_execution_id:step.step_execution_id,output_version:run.output_version,view_type:filter.status==='all'?'input':filter.status,limit:'12'});
  if(cursor)params.set('cursor',cursor);if(filter.tag.startsWith('reason:'))params.set('reason_code',filter.tag.slice(7));if(filter.tag.startsWith('rule:'))params.set('rule_id',filter.tag.slice(5));if(filter.query)params.set('query',filter.query);
  try{
   const response=await fetch(`/v1/retrieval/tasks/${encodeURIComponent(taskId)}/nodes/cleaning/outputs?`+params,{headers,cache:'no-store',signal:requestAbort.signal});const data=await response.json();if(!current(e))return;if(!response.ok)throw new Error(`${data.code||response.status}: ${data.message||'读取失败'}`);
   if(data.output_version!==run.output_version||data.revision!==run.revision||data.generation!==run.generation||data.operation_id!==run.operation_id||data.step_execution_id!==step.step_execution_id||data.items.length>12)throw new Error('清洗输出版本已变化，请刷新结果');
   page=target;cursors[page]=cursor;nextCursor=data.next_cursor;loaded=true;count.textContent=`第 ${page+1} 页 · 匹配 ${data.total_items} 张 · 本页 ${data.items.length} 张`;
   for(const item of data.items){
    const row=document.createElement('article');row.className='cleaning-image';grid.append(row);rows.add(row);const canPreview=preview&&item.preview_status==='available';
    row._asset={title:'清洗图片 · '+item.candidate_id,url:canPreview?`/v1/retrieval/tasks/${encodeURIComponent(taskId)}/cleaning/candidates/${encodeURIComponent(item.candidate_id)}/preview`:null,lines:()=>['本步结论：'+({retained:'本步保留',rejected:'淘汰',review:'待复核',pending:'未完成',blocked:'阻塞'})[item.status],'素材版本：'+item.asset_version,'步骤：'+step.step_id,'输出版本：'+run.output_version,...item.reasons.map(boardCleaningReason),...(node?['对应诉求：'+node.source,'执行指令：'+node.instruction]:[])]};
    const button=cleaningText(row,'button',canPreview?'加载缩略图…':'暂无可用缩略图');button.className='cleaning-thumbnail';button.setAttribute('aria-label','查看清洗图片与证据');button.onclick=()=>openAssetViewer(row);
    const caption=document.createElement('div');caption.className='media-caption';row.append(caption);cleaningText(caption,'strong',({retained:'本步保留',rejected:'淘汰',review:'待复核',pending:'未完成',blocked:'阻塞'})[item.status]||item.status);const reason=cleaningText(caption,'p',item.reasons.map(reason=>reason.reason_summary?(reason.reason_summary+(reason.reason_truncated?'（摘要已截断）':'')):({MATCH:'符合条件',MISMATCH:'不符合条件',FACT_UNAVAILABLE:'证据不足',DETECTOR_ERROR:'检测器异常',DETECTOR_OUTPUT_INVALID:'检测结果格式无效'})[reason.reason_code]||'查看详情了解原因').join('；')||'暂无判定原因');reason.className='media-reason';
    const details=cleaningText(row,'button','查看完整原因与证据');details.className='media-details';details.onclick=()=>openAssetViewer(row);if(canPreview)boardCleaningImage(taskId,item.candidate_id,row,button,token);
   }
  }catch(error){if(current(e)&&error.name!=='AbortError'){count.textContent='图片读取失败：'+error.message;retry.hidden=false;retry.onclick=()=>load(target,cursor)}}finally{if(current(e)){loading=false;buttons()}}
 }
 const reset=()=>{cursors=[null];page=0;nextCursor=null;loaded=false;if(detail.open)return load();buttons()};
 select.onchange=()=>{filter.status=select.value;return reset()};tags.onchange=()=>{filter.tag=tags.value;return reset()};query.oninput=()=>{filter.query=query.value.trim();epoch++;loading=true;buttons();requestAbort?.abort();release();clearTimeout(searchTimer);searchTimer=setTimeout(reset,250)};
 prev.onclick=()=>page>0?load(page-1,cursors[page-1]):undefined;next.onclick=()=>nextCursor?load(page+1,nextCursor):undefined;
 detail.addEventListener('toggle',()=>{if(detail.open){if(cleaningPanel.deactivate!==deactivate)cleaningPanel.deactivate?.();cleaningPanel.deactivate=deactivate;cleaningPanel.openKey=key;tab.setAttribute('aria-selected','true');filter.expanded=true;if(!loaded&&!loading)load(page,cursors[page])}else deactivate()});
 buttons();if(cleaningPanel.openKey===key||(cleaningPanel.openKey===null&&!cleaningPanel.firstStep)){cleaningPanel.firstStep=detail;detail.open=true;tab.setAttribute('aria-selected','true');filter.expanded=true;cleaningPanel.openKey=key;cleaningPanel.deactivate=deactivate;load()}

}
async function readBoardCleaning(){const taskId=cleaningPanel.taskId;if(!taskId)return;clearBoardCleaning();const token=++cleaningPanel.token;cleaningPanel.abort=new AbortController();const current=()=>token===cleaningPanel.token&&taskId===cleaningPanel.taskId&&!$('board-cleaning').hidden;const body=$('board-cleaning-body');body.replaceChildren();$('board-cleaning-status').textContent='正在读取当前版本清洗记录…';try{const base=`/v1/retrieval/tasks/${encodeURIComponent(taskId)}`;const [task,data]=await Promise.all([api(base+'/read-binding').then(binding=>binding.task),api(base+'/cleaning/steps?summary=true')]);if(!current())return;const operationId=task.active_cleaning_operation_id||data.runs?.[0]?.operation_id;const activeRun=data.runs?.find(run=>run.operation_id===operationId);const status=operationId&&activeRun?.status!=='completed'?await api(base+'/cleaning/status?operation_id='+encodeURIComponent(operationId)):null;if(!current())return;const latest=(await api(base+'/read-binding')).task;if(!current())return;if(data.revision!==task.confirmed_revision||data.generation!==task.run_generation||task.task_version!==latest.task_version||task.run_generation!==latest.run_generation||task.confirmed_revision!==latest.confirmed_revision)throw new Error('任务版本已变化，请刷新结果');$('board-cleaning-title').textContent='清洗结果';const progress=status?.progress;$('board-cleaning-status').textContent=progress?`已完整判定 ${progress.completed}/${progress.total} 张 · 通过 ${progress.passed} · 淘汰 ${progress.rejected} · 待复核 ${progress.review} · 未完成 ${progress.pending}`:data.available?'':'暂无逐图结果';if(status?.status==='retry_wait')cleaningText(body,'p',`等待重试 ${status.attempts}/${status.max_attempts}；下次不早于 ${new Date(status.next_attempt_at*1000).toLocaleTimeString()}`);if(status?.status==='failed')cleaningText(body,'p',`清洗已停止：${status.code}；${status.message}`);if(status?.status==='superseded')throw new Error('清洗所属版本已失效，请刷新线路');if(data.available){for(const [runIndex,run] of data.runs.entries()){const runBody=runIndex?document.createElement('details'):body;if(runIndex){runBody.className='cleaning-history-run';body.append(runBody);cleaningText(runBody,'summary',`历史清洗运行 ${runIndex}`)}const metadata=document.createElement('details');metadata.className='cleaning-node-info';runBody.append(metadata);cleaningText(metadata,'summary','运行与模型信息');cleaningText(metadata,'p',`运行 ${run.operation_id} · revision ${run.revision} · generation ${run.generation}`);boardCleaningSnapshot(metadata,run.execution);const chain=document.createElement('div');chain.className='cleaning-chain';runBody.append(chain);chain._nav=document.createElement('div');chain._nav.className='cleaning-step-nav';chain._nav.setAttribute('aria-label','清洗步骤');chain._results=document.createElement('div');chain._results.className='cleaning-step-results';chain.append(chain._nav,chain._results);run.steps.forEach((step,index)=>boardCleaningStep(chain,run,step,taskId,data.candidate_preview_available,token,index))}}else{boardCleaningSnapshot(body,status?.execution);cleaningText(body,'p',operationId?'尚未发布完整步骤结果，已保存判定见下方；未完成的图片不计为待复核。':'尚未启动已批准的清洗操作。');for(const item of progress?.candidate_results||[])cleaningText(body,'p',item.candidate_id+'：'+({pass:'通过',fail:'淘汰',unknown:'待复核'})[item.verdict]);if(progress?.partial_candidate){cleaningText(body,'h3','当前图片 '+progress.partial_candidate);for(const node of progress.completed_nodes||[])cleaningText(body,'p',`${node.step_id}：${({pass:'通过',fail:'淘汰',unknown:'待复核'})[node.verdict]||node.verdict} · ${node.reasons.map(reason=>reason.reason_summary||reason.reason_code).join('；')}`);cleaningText(body,'p','下一节点：'+(progress.next_node||'等待本图完整保存'))}}if(['queued','running','retry_wait'].includes(status?.status))cleaningPanel.timer=setTimeout(()=>{if(current())readBoardCleaning()},3000)}catch(error){if(current()){$('board-cleaning-status').textContent='清洗详情读取失败：'+error.message;body.replaceChildren()}}}
function openBoardCleaning(taskId){closeBoardCleaning();cleaningPanel.filters.clear();cleaningPanel.taskId=taskId;$('board-cleaning').hidden=false;readBoardCleaning()}
$('board-cleaning-refresh').onclick=readBoardCleaning;
'''
